package fr.formation.clean.application.usecase;
import fr.formation.clean.application.boundary.*;import fr.formation.clean.domain.entity.*;import java.util.UUID;
public final class CreateReservationInteractor implements CreateReservationInputBoundary{private final RoomGateway rooms;private final ReservationGateway reservations;private final NotificationGateway notifications;public CreateReservationInteractor(RoomGateway rooms,ReservationGateway reservations,NotificationGateway notifications){this.rooms=rooms;this.reservations=reservations;this.notifications=notifications;}public Output execute(Input i){var room=rooms.findById(i.roomId()).orElseThrow(()->new UseCaseException("Room not found"));if(!room.accepts(i.participants()))throw new DomainException("Room capacity exceeded");var candidate=new Reservation(UUID.randomUUID(),i.roomId(),i.organizerEmail(),i.participants(),i.startsAt(),i.endsAt(),Reservation.Status.CONFIRMED);if(reservations.hasOverlap(i.roomId(),i.startsAt(),i.endsAt()))throw new DomainException("Room unavailable");var saved=reservations.save(candidate);notifications.sendConfirmation(i.organizerEmail());return new Output(saved.id(),saved.roomId(),saved.organizerEmail(),saved.participants(),saved.startsAt(),saved.endsAt(),saved.status().name());}}
